// Configuration : l'événement de la plateforme est prioritaire ; sinon valeurs posées à l'import (n8n/setup_n8n.py).
const CFG = { platform_url: '__PLATFORM_URL__', telegram_chat_id: '__TELEGRAM_CHAT_ID__', llm_model: '__LLM_MODEL__' };
const DEF = { platform_url: 'http://localhost:8000', telegram_chat_id: '', llm_model: 'claude-sonnet-5-5' };
const cfg = (k, v) => v || (String(CFG[k]).startsWith('__') ? DEF[k] : CFG[k]);
// n8n (Node) résout « localhost » en IPv6 (::1) alors que la plateforme écoute en IPv4 : on force 127.0.0.1.
const platformUrl = (v) => cfg('platform_url', v).replace(/\/$/, '').replace('//localhost', '//127.0.0.1');

// Consigne de l'agent PredictionAgent — source : dashboard/app/agents/specs.py
const SYSTEM = "Tu es un assistant d'aide à la décision d'une clinique (Hospital Copilot). Règles : n'invente JAMAIS de valeur ; cite les valeurs fournies ; respecte strictement les allergies et les traitements en cours ; tu ne poses pas de diagnostic et tu ne prescris rien : tu expliques, synthétises et suggères, un soignant valide. La détection et la sévérité sont déjà fixées par des règles déterministes : ne les modifie pas. Réponds en français, UNIQUEMENT par un objet JSON valide, sans texte autour et sans balise Markdown.\nUn score déterministe estime qu'un patient hospitalisé risque une crise (condition, risque sur 100, fenêtre de temps approximative, facteurs fournis). Explique en 3 phrases au plus pourquoi le risque est à ce niveau en citant les facteurs et les valeurs, puis propose 3 à 4 conduites à tenir concrètes pour l'infirmier et le médecin de garde. Rappelle que c'est une estimation de prototype, non validée cliniquement. Ne modifie ni le risque ni la fenêtre ; n'annonce pas la crise comme certaine.";
const FORMAT = "{\"explanation\": \"3 phrases au plus\", \"conduct\": [\"conduite à tenir\"]}";

const body = $input.first().json.body || {};
if (!body.ref) throw new Error('événement crisis-prediction sans référence');
const context = body.context || {};
const model = cfg('llm_model', body.llm_model);
const user = `Contexte (JSON) :\n${JSON.stringify(context, null, 1)}\n\nFormat exact attendu :\n${FORMAT}`;
return [{ json: {
  started_at: Date.now(), workflow: 'crisis-prediction', ref: String(body.ref), room: body.room || '', risk_id: body.risk_id ?? null,
  platform_url: platformUrl(body.platform_url), chat_id: cfg('telegram_chat_id', body.telegram_chat_id), model, context,
  request: { model, max_tokens: 8000, system: SYSTEM, messages: [{ role: 'user', content: user }] },
} }];

// Extrait l'objet JSON de la réponse Anthropic et vérifie les clés obligatoires.
const REQUIRED = ["explanation"];
const ctx = $('Construire le prompt').first().json;
const res = $input.first().json;
let result = null, error = null;
try {
  if (!res || res.error) throw new Error(typeof (res || {}).error === 'string' ? res.error : ((res || {}).error || {}).message || 'appel Anthropic en échec');
  const text = (res.content || []).filter((b) => b.type === 'text').map((b) => b.text).join('');
  if (!text) throw new Error('réponse vide');
  if (res.stop_reason === 'max_tokens') throw new Error('réponse tronquée (max_tokens)');
  const m = text.match(/\{[\s\S]*\}/);
  result = JSON.parse(m ? m[0] : text);
  const missing = REQUIRED.filter((k) => result[k] === undefined || result[k] === null || result[k] === '' || (Array.isArray(result[k]) && !result[k].length));
  if (missing.length) throw new Error('clé(s) manquante(s) : ' + missing.join(', '));
} catch (e) { error = e.message; result = null; }
const fallback = result === null;
return [{ json: {
  platform_url: ctx.platform_url, chat_id: ctx.chat_id, fallback, error,
  // en secours, le contexte repart vers la plateforme : elle construit la réponse déterministe de l'agent
  payload: { workflow: ctx.workflow, ref: ctx.ref, result, context: fallback ? ctx.context : null, fallback, error, model: (res && res.model) || ctx.model, anthropic_id: (res && res.id) || null,
             room: ctx.room || null, risk_id: ctx.risk_id, duration_ms: Date.now() - ctx.started_at },
} }];
